  1	import { randomInt } from "node:crypto";
  2	import { performance } from "node:perf_hooks";
  3	import { ErrorCode, matchMaker, Room, ServerError, type AuthContext, type Client } from "colyseus";
  4	import {
  5	  createDuelOptionsSchema,
  6	  DUEL_CODE_REQUIRED_MESSAGE,
  7	  DUEL_COUNTDOWN_FRAMES,
  8	  DUEL_RECONNECT_SECONDS,
  9	  DUEL_ROOM,
 10	  DUEL_UNAVAILABLE_MESSAGE,
 11	  duelFullMessage,
 12	  DuelMessageType,
 13	  duelPracticeMessageSchema,
 14	  duelProbeReplySchema,
 15	  joinDuelOptionsSchema,
 16	  JoinRefusal,
 17	  MAX_INPUT_MESSAGES_PER_SECOND,
 18	  NO_SUCH_DUEL_MESSAGE,
 19	  PROTOCOL_VERSION,
 20	  type DuelEndReason,
 21	  type DuelProbe,
 22	  type DuelRoomPhase,
 23	  type DummyBehaviour,
 24	} from "@pirate-sea-race/protocol";
 25	import { createDuelState, defaultDuelConfig, duelInput, type DuelState, type PlayerIndex } from "@pirate-sea-race/simulation/duel";
 26	import { chooseInputDelay, DuelAuthority, linkStats, type AuthorityStats } from "@pirate-sea-race/simulation/netcode";
 27	import { admitSeat, authorizePrivateEntry, type AdmissionRules } from "./admission.js";
 28	import { DuelInputGate } from "./duelInputGate.js";
 29	import type { MatchMetadata } from "./MatchRoom.js";
 30	import { generateMatchCode } from "./matchCode.js";
 31	import { DuelRoomStateSchema, DuelSeatSchema } from "./schema.js";
 32	
 33	const STEPS_PER_SECOND = 60;
 34	/** The lobby state goes out at 20 Hz; the duel's frames travel as messages. */
 35	const PATCH_INTERVAL_MS = 1000 / 20;
 36	/** Round-trip probes: every 6 frames during the countdown (for the input delay), every 30 during the fight (the HUD). */
 37	const COUNTDOWN_PROBE_FRAMES = 6;
 38	const FIGHT_PROBE_FRAMES = 30;
 39	/** Round-trip samples kept per seat. */
 40	const PROBE_SAMPLES = 25;
 41	/** The input delay is chosen this many frames before the countdown ends, from the probes measured until then. */
 42	export const DELAY_DECISION_FRAMES = 30;
 43	
 44	/** A duel's admission: the `duel` listing, the duel option schemas and the duel refusal messages. */
 45	const DUEL_ADMISSION: AdmissionRules = {
 46	  roomName: DUEL_ROOM,
 47	  createSchema: createDuelOptionsSchema,
 48	  joinSchema: joinDuelOptionsSchema,
 49	  noSuchMessage: NO_SUCH_DUEL_MESSAGE,
 50	  codeRequiredMessage: DUEL_CODE_REQUIRED_MESSAGE,
 51	  fullMessage: duelFullMessage,
 52	};
 53	
 54	/** Checks a create or join request for a duel before matchmaking places it (see `authorizePrivateEntry`). */
 55	export function authorizeDuelEntry(options: unknown): Promise<true> {
 56	  return authorizePrivateEntry(options, DUEL_ADMISSION);
 57	}
 58	
 59	interface Seat {
 60	  readonly slot: PlayerIndex;
 61	  readonly gate: DuelInputGate;
 62	  readonly schema: DuelSeatSchema;
 63	  /** Probe ids in flight and when they were sent (performance.now()). */
 64	  readonly probes: Map<number, number>;
 65	  readonly rtts: number[];
 66	  nextProbe: number;
 67	}
 68	
 69	/** What the room reports to tests and diagnostics about a finished or running duel. */
 70	export interface DuelDiagnostics {
 71	  readonly phase: DuelRoomPhase;
 72	  readonly frame: number;
 73	  readonly inputDelay: number;
 74	  readonly authority: AuthorityStats;
 75	  /** Input messages the gate dropped, per slot and reason. */
 76	  readonly dropped: Record<string, DuelInputGate["dropped"]>;
 77	  readonly rttSamples: Record<string, readonly number[]>;
 78	}
 79	
 80	/**
 81	 * One standalone duel (the combat spike, §18 stage 1), privately admitted like a match: created with a one-time token,
 82	 * joined by its code, two players (or one against the server's dummy in practice). The countdown starts once every
 83	 * seat is taken; during it the room probes both round trips and, DELAY_DECISION_FRAMES before the end, chooses the
 84	 * shared input delay. It then steps `stepDuel` at 60 Hz through `DuelAuthority` (first copy of each frame's input
 85	 * wins, late input never rewrites a frame, the held input repeats for 250 ms and then neutral) and broadcasts a frame
 86	 * bundle every third frame. The step's result ends the duel, and so does a player absent past DUEL_RECONNECT_SECONDS.
 87	 */
 88	export class DuelRoom extends Room<{ state: DuelRoomStateSchema; metadata: MatchMetadata }> {
 89	  override maxClients = 2;
 90	  /** A flood ceiling: past it Colyseus disconnects the client. Excess input is dropped well below it, in the gate. */
 91	  override maxMessagesPerSecond = MAX_INPUT_MESSAGES_PER_SECOND * 4;
 92	  override patchRate = PATCH_INTERVAL_MS;
 93	  override state = new DuelRoomStateSchema();
 94	
 95	  private readonly config = defaultDuelConfig;
 96	  private authority!: DuelAuthority;
 97	  private readonly seats = new Map<string, Seat>();
 98	  private createToken: string | undefined;
 99	  private tick = 0;
100	
101	  static override async onAuth(_token: string, options: unknown, _context: AuthContext): Promise<true> {
102	    return authorizeDuelEntry(options);
103	  }
104	
105	  override async onCreate(options: unknown): Promise<void> {
106	    const parsed = createDuelOptionsSchema.safeParse(options);
107	    if (!parsed.success) throw new ServerError(ErrorCode.MATCHMAKE_INVALID_CRITERIA, DUEL_UNAVAILABLE_MESSAGE);
108	    this.createToken = parsed.data.createToken;
109	    const practice = parsed.data.practice === true;
110	    this.maxClients = practice ? 1 : 2;
111	    const code = await this.allocateCode();
112	    const seed = randomInt(0, 2 ** 32);
113	    this.authority = new DuelAuthority(this.config, createDuelState(this.config, { seed }));
114	    this.state.code = code;
115	    this.state.protocolVersion = PROTOCOL_VERSION;
116	    this.state.practice = practice;
117	    this.state.dummy = practice ? "idle" : "";
118	    this.state.phase = "waiting";
119	    this.state.countdown = DUEL_COUNTDOWN_FRAMES;
120	    this.state.seed = seed;
121	    this.state.winner = -1;
122	    if (practice) this.authority.script(1, (state) => this.dummyInput(state));
123	    // As for matches: the create request's token was copied into the listing; replacing the metadata drops it.
124	    await this.setMatchmaking({ metadata: { code, custom: true } });
125	
126	    this.onMessage(DuelMessageType.Input, (client, message: unknown) => this.receiveInput(client, message));
127	    this.onMessage(DuelMessageType.Probe, (client, message: unknown) => this.receiveProbeReply(client, message));
128	    this.onMessage(DuelMessageType.Practice, (_client, message: unknown) => {
129	      const request = duelPracticeMessageSchema.safeParse(message);
130	      if (this.state.practice && request.success) this.state.dummy = request.data.dummy;
131	    });
132	    // Unknown message types are dropped, not answered: Colyseus would otherwise disconnect the sender.
133	    this.onMessage("*", () => undefined);
134	    this.setFixedTimestep(() => this.advance(), STEPS_PER_SECOND);
135	  }
136	
137	  override onJoin(client: Client, options: unknown): void {
138	    this.createToken = admitSeat(options, { code: this.state.code, createToken: this.createToken }, DUEL_ADMISSION);
139	    const taken = new Set([...this.seats.values()].map((seat) => seat.slot));
140	    const slot: PlayerIndex = taken.has(0) ? 1 : 0;
141	    const schema = new DuelSeatSchema();
142	    schema.sessionId = client.sessionId;
143	    schema.slot = slot;
144	    schema.connected = true;
145	    this.state.seats.push(schema);
146	    this.seats.set(client.sessionId, { slot, gate: new DuelInputGate(), schema, probes: new Map(), rtts: [], nextProbe: 1 });
147	    if (this.state.phase === "waiting" && this.seats.size === this.maxClients) {
148	      this.state.phase = "countdown";
149	      void this.lock();
150	    }
151	  }
152	
153	  /** A player dropped without leaving: their seat is kept for DUEL_RECONNECT_SECONDS, then they forfeit (§12). */
154	  override onDrop(client: Client): void {
155	    const seat = this.seats.get(client.sessionId);
156	    if (seat === undefined || this.state.phase === "over") return;
157	    seat.schema.connected = false;
158	    seat.probes.clear();
159	    void this.allowReconnection(client, DUEL_RECONNECT_SECONDS).catch(() => undefined);
160	  }
161	
162	  /** The same player is back: they continue from the authoritative state, which a snapshot bundle gives them. */
163	  override onReconnect(client: Client): void {
164	    const seat = this.seats.get(client.sessionId);
165	    if (seat === undefined) return;
166	    seat.schema.connected = true;
167	    if (this.state.phase === "fighting" || this.state.phase === "over") client.send(DuelMessageType.Frames, this.authority.snapshotBundle());
168	  }
169	
170	  /** A player left for good (quit, or absent past the reconnection window): before the countdown their seat frees up. */
171	  override onLeave(client: Client): void {
172	    const seat = this.seats.get(client.sessionId);
173	    if (seat === undefined) return;
174	    seat.schema.connected = false;
175	    if (this.state.phase === "waiting") {
176	      this.seats.delete(client.sessionId);
177	      const index = this.state.seats.findIndex((entry) => entry.sessionId === client.sessionId);
178	      if (index >= 0) this.state.seats.splice(index, 1);
179	      return;
180	    }
181	    if (this.state.phase === "countdown" || this.state.phase === "fighting") {
182	      const opponent: PlayerIndex = seat.slot === 0 ? 1 : 0;
183	      this.finish(opponent, "forfeit", Math.max(0, this.authority.frame));
184	    }
185	  }
186	
187	  /** Inputs dropped per client and reason, for tests and diagnostics. */
188	  droppedInputs(sessionId: string): DuelInputGate["dropped"] | undefined {
189	    return this.seats.get(sessionId)?.gate.dropped;
190	  }
191	
192	  /** The duel's counters, for tests and the harness. */
193	  diagnostics(): DuelDiagnostics {
194	    const bySlot = <T>(pick: (seat: Seat) => T) => Object.fromEntries([...this.seats.values()].map((seat) => [String(seat.slot), pick(seat)]));
195	    return {
196	      phase: this.state.phase as DuelRoomPhase,
197	      frame: this.authority.frame,
198	      inputDelay: this.state.inputDelay,
199	      authority: structuredClone(this.authority.stats),
200	      dropped: bySlot((seat) => ({ ...seat.gate.dropped })),
201	      rttSamples: bySlot((seat) => [...seat.rtts]),
202	    };
203	  }
204	
205	  /** The authoritative duel state, for tests. */
206	  get duelState(): DuelState {
207	    return this.authority.state;
208	  }
209	
210	  /** Every input pair applied so far as a replayable log, for tests. */
211	  inputLog(): ReturnType<DuelAuthority["inputLog"]> {
212	    return this.authority.inputLog();
213	  }
214	
215	  /** The duel's frame on one timeline: negative during the countdown, then the frames stepped. */
216	  private get serverFrame(): number {
217	    return this.state.phase === "countdown" || this.state.phase === "waiting" ? -this.state.countdown : this.authority.frame;
218	  }
219	
220	  private receiveInput(client: Client, message: unknown): void {
221	    const seat = this.seats.get(client.sessionId);
222	    if (seat === undefined || (this.state.phase !== "countdown" && this.state.phase !== "fighting")) return;
223	    const input = seat.gate.receive(message, this.tick, this.serverFrame);
224	    if (input === undefined || (this.state.practice && seat.slot !== 0)) return;
225	    this.authority.receive(seat.slot, input.frame, input.inputs);
226	  }
227	
228	  private receiveProbeReply(client: Client, message: unknown): void {
229	    const seat = this.seats.get(client.sessionId);
230	    const reply = duelProbeReplySchema.safeParse(message);
231	    if (seat === undefined || !reply.success) return;
232	    const sentAt = seat.probes.get(reply.data.id);
233	    if (sentAt === undefined) return;
234	    seat.probes.delete(reply.data.id);
235	    seat.rtts.push(performance.now() - sentAt);
236	    if (seat.rtts.length > PROBE_SAMPLES) seat.rtts.shift();
237	    seat.schema.rtt = Math.round(linkStats(seat.rtts)!.rttMs);
238	  }
239	
240	  private sendProbes(): void {
241	    for (const client of this.clients) {
242	      const seat = this.seats.get(client.sessionId);
243	      if (seat === undefined || !seat.schema.connected) continue;
244	      const id = seat.nextProbe++;
245	      seat.probes.set(id, performance.now());
246	      // Probes that never came back (a dropped connection) are forgotten after a few seconds' worth.
247	      for (const old of seat.probes.keys()) if (old < id - 20) seat.probes.delete(old);
248	      const probe: DuelProbe = { id, frame: this.serverFrame, rtt: seat.rtts.length === 0 ? 0 : linkStats(seat.rtts)!.rttMs };
249	      client.send(DuelMessageType.Probe, probe);
250	    }
251	  }
252	
253	  private advance(): void {
254	    this.tick++;
255	    switch (this.state.phase) {
256	      case "countdown":
257	        this.state.countdown--;
258	        if (this.state.countdown % COUNTDOWN_PROBE_FRAMES === 0) this.sendProbes();
259	        if (this.state.countdown === DELAY_DECISION_FRAMES) {
260	          this.state.inputDelay = chooseInputDelay([...this.seats.values()].map((seat) => linkStats(seat.rtts)));
261	        }
262	        if (this.state.countdown === 0) {
263	          this.state.phase = "fighting";
264	          this.broadcast(DuelMessageType.Frames, this.authority.snapshotBundle());
265	        }
266	        return;
267	      case "fighting": {
268	        const bundle = this.authority.step();
269	        if (bundle !== undefined) this.broadcast(DuelMessageType.Frames, bundle);
270	        if (this.authority.frame % FIGHT_PROBE_FRAMES === 0) this.sendProbes();
271	        const result = this.authority.state.result;
272	        if (result !== null) this.finish(result.winner, result.reason, result.frame);
273	        return;
274	      }
275	      default:
276	        return;
277	    }
278	  }
279	
280	  /** Ends the duel: the step's result, or a forfeit. Both players see it in the room state. */
281	  private finish(winner: PlayerIndex | null, reason: DuelEndReason, frame: number): void {
282	    if (this.state.phase === "over") return;
283	    this.state.phase = "over";
284	    this.state.winner = winner ?? -1;
285	    this.state.reason = reason;
286	    this.state.resultFrame = frame;
287	  }
288	
289	  /**
290	   * The practice dummy (§13's idle or defensive opponent): idle, or guarding. A guarding dummy holds back (away from
291	   * player one) while player one strikes and while it is in blockstun, and stands still otherwise, so it neither
292	   * backs out of range nor escapes a throw (throws beat guard).
293	   */
294	  private dummyInput(state: DuelState): number {
295	    if ((this.state.dummy as DummyBehaviour) !== "guard") return 0;
296	    const [player, dummy] = state.fighters;
297	    const striking = player.action === "attack" && player.moveId !== this.config.moveset.commands.throw;
298	    if (!striking && dummy.action !== "blockstun") return 0;
299	    return duelInput(dummy.x >= player.x ? "right" : "left");
300	  }
301	
302	  private async allocateCode(): Promise<string> {
303	    for (let attempt = 0; attempt < 16; attempt++) {
304	      const code = generateMatchCode();
305	      const taken = await matchMaker.query({ name: this.roomName, code });
306	      if (taken.length === 0) return code;
307	    }
308	    throw new ServerError(JoinRefusal.BadRequest, "Could not allocate a duel code");
309	  }
310	}

