  1	import { z } from "zod";
  2	import { createTokenSchema, matchCodeSchema } from "./join.js";
  3	import { encodedSize, MAX_INPUT_LEAD_FRAMES, MAX_INPUT_MESSAGE_BYTES, MAX_SEQUENCE, type InputContext, type InputRejection } from "./input.js";
  4	
  5	/** The Colyseus room name of a standalone duel (the combat spike, §18 stage 1). */
  6	export const DUEL_ROOM = "duel";
  7	
  8	export const DuelMessageType = {
  9	  /** Client → server: batched, redundant frame-tagged duel inputs (`DuelInputMessage`). */
 10	  Input: "duel-input",
 11	  /** Server → client: the inputs the server applied since the last bundle, with a snapshot or a hash (`DuelFrameBundle`). */
 12	  Frames: "duel-frames",
 13	  /** Both ways: a round-trip probe from the server (`DuelProbe`) and the client's echo (`DuelProbeReply`). */
 14	  Probe: "duel-probe",
 15	  /** Client → server, practice rooms only: the dummy's behaviour (`DuelPracticeMessage`). */
 16	  Practice: "duel-practice",
 17	} as const;
 18	
 19	/**
 20	 * The highest duel input: every bit of `DUEL_INPUT` (content's `DUEL_INPUT_MASK`, which the protocol does not depend
 21	 * on). A server unit test keeps the two equal.
 22	 */
 23	export const DUEL_INPUT_BITS_MAX = 0x1ff;
 24	
 25	/** Inputs one message carries at most: the newest frame and the three before it. */
 26	export const MAX_DUEL_INPUTS_PER_MESSAGE = 4;
 27	/** Clients send input messages at most this often (every second frame), half the gate's cap. */
 28	export const DUEL_INPUT_MESSAGES_PER_SECOND = 30;
 29	/** The server sends one frame bundle every this many frames (20 a second)... */
 30	export const DUEL_BUNDLE_FRAMES = 3;
 31	/** ...and a full snapshot in every this many bundles (every 6 frames); the others carry the state hash. */
 32	export const DUEL_SNAPSHOT_EVERY_BUNDLES = 2;
 33	/** The countdown before the fight, in frames (§6: three seconds). */
 34	export const DUEL_COUNTDOWN_FRAMES = 180;
 35	/** A player absent this long forfeits (§12); they may rejoin the same duel until then. */
 36	export const DUEL_RECONNECT_SECONDS = 10;
 37	
 38	/**
 39	 * One client's duel input message (§15, batched and redundant): `inputs` holds the input bits (`DUEL_INPUT`) of
 40	 * consecutive frames, oldest first, ending with frame `frame`; so `inputs[k]` is for frame
 41	 * `frame - inputs.length + 1 + k`. A client repeats each frame in two messages, so one lost message loses no input.
 42	 * The server takes each frame's input from the first message that carries it and ignores frames it has already
 43	 * stepped. It is checked like world input: size, strictly increasing `seq`, and `frame` no more than
 44	 * MAX_INPUT_LEAD_FRAMES ahead of the server.
 45	 */
 46	export const duelInputMessageSchema = z.strictObject({
 47	  seq: z.int().min(1).max(MAX_SEQUENCE),
 48	  frame: z.int().min(1).max(MAX_SEQUENCE),
 49	  inputs: z.array(z.int().min(0).max(DUEL_INPUT_BITS_MAX)).min(1).max(MAX_DUEL_INPUTS_PER_MESSAGE),
 50	});
 51	
 52	export type DuelInputMessage = z.infer<typeof duelInputMessageSchema>;
 53	
 54	export type DuelInputValidation = { ok: true; input: DuelInputMessage } | { ok: false; reason: InputRejection };
 55	
 56	/** The first frame a duel input message carries. */
 57	export function firstInputFrame(message: Pick<DuelInputMessage, "frame" | "inputs">): number {
 58	  return message.frame - message.inputs.length + 1;
 59	}
 60	
 61	/**
 62	 * Validates an untrusted duel input message with the world input's limits: MAX_INPUT_MESSAGE_BYTES, the schema, a
 63	 * sequence number above the last accepted one, and a newest frame at most MAX_INPUT_LEAD_FRAMES past the server's.
 64	 * The server's frame is negative during the countdown (frames left until the fight's frame 0).
 65	 */
 66	export function validateDuelInputMessage(message: unknown, context: InputContext): DuelInputValidation {
 67	  const size = encodedSize(message);
 68	  if (size === undefined) return { ok: false, reason: "malformed" };
 69	  if (size > MAX_INPUT_MESSAGE_BYTES) return { ok: false, reason: "oversized" };
 70	  const parsed = duelInputMessageSchema.safeParse(message);
 71	  if (!parsed.success) return { ok: false, reason: "malformed" };
 72	  const input = parsed.data;
 73	  if (input.seq <= context.lastAcceptedSeq) return { ok: false, reason: "stale-sequence" };
 74	  if (input.frame > context.serverFrame + MAX_INPUT_LEAD_FRAMES) return { ok: false, reason: "future-frame" };
 75	  return { ok: true, input };
 76	}
 77	
 78	/**
 79	 * Server → client, one per DUEL_BUNDLE_FRAMES: the inputs the server applied to both players, substitutions included,
 80	 * for each frame since the last bundle, ending with frame `frame`. `inputs[k]` is `[player one, player two]` for frame
 81	 * `frame - inputs.length + 1 + k`. `substituted` has bit `2k + p` set when player `p`'s input for that frame was not
 82	 * received in time (the held input repeated, or neutral). Every DUEL_SNAPSHOT_EVERY_BUNDLES-th bundle carries the full
 83	 * state after `frame` as `snapshot` (a `DuelSnapshot`, checked by `restoreDuel`); the others carry its `hashState` as
 84	 * `hash`. A bundle with no inputs and a snapshot is a resync point (the fight's frame 0, or a rejoin).
 85	 */
 86	export const duelFrameBundleSchema = z.strictObject({
 87	  frame: z.int().min(0).max(MAX_SEQUENCE),
 88	  inputs: z.array(z.tuple([z.int().min(0).max(DUEL_INPUT_BITS_MAX), z.int().min(0).max(DUEL_INPUT_BITS_MAX)])),
 89	  substituted: z.int().min(0),
 90	  snapshot: z.unknown().optional(),
 91	  hash: z.string().regex(/^[0-9a-f]{16}$/).optional(),
 92	});
 93	
 94	export type DuelFrameBundle = z.infer<typeof duelFrameBundleSchema>;
 95	
 96	/**
 97	 * Server → client round-trip probe: `id` to echo, the server's duel `frame` when it was sent (negative during the
 98	 * countdown), and `rtt`, the server's latest round-trip measurement for this client in milliseconds (0 before any).
 99	 */
100	export const duelProbeSchema = z.strictObject({
101	  id: z.int().min(1).max(MAX_SEQUENCE),
102	  frame: z.int(),
103	  rtt: z.number().min(0),
104	});
105	
106	export type DuelProbe = z.infer<typeof duelProbeSchema>;
107	
108	/** Client → server: the echo of a probe, sent as soon as it arrives. */
109	export const duelProbeReplySchema = z.strictObject({ id: z.int().min(1).max(MAX_SEQUENCE) });
110	
111	export type DuelProbeReply = z.infer<typeof duelProbeReplySchema>;
112	
113	/** A practice dummy either stands idle or holds back to guard (§13's idle or defensive opponent). */
114	export const DUMMY_BEHAVIOURS = ["idle", "guard"] as const;
115	export type DummyBehaviour = (typeof DUMMY_BEHAVIOURS)[number];
116	
117	export const duelPracticeMessageSchema = z.strictObject({ dummy: z.enum(DUMMY_BEHAVIOURS) });
118	
119	export type DuelPracticeMessage = z.infer<typeof duelPracticeMessageSchema>;
120	
121	/** Creating a duel: like a match, with a one-time token; `practice` makes a one-player room against the dummy. */
122	export const createDuelOptionsSchema = z.object({
123	  protocolVersion: z.int(),
124	  createToken: createTokenSchema,
125	  practice: z.boolean().optional(),
126	});
127	
128	/** Joining a duel by its code. */
129	export const joinDuelOptionsSchema = z.object({
130	  protocolVersion: z.int(),
131	  code: matchCodeSchema,
132	});
133	
134	export type CreateDuelOptions = z.infer<typeof createDuelOptionsSchema>;
135	export type JoinDuelOptions = z.infer<typeof joinDuelOptionsSchema>;
136	
