    22	
    23	  /** A message stamped with server frame `serverFrame` arrived at `arrivalMs`, with the round trip currently `rttMs`. */
    24	  observe(serverFrame: number, arrivalMs: number, rttMs: number): void {
    25	    this.samples.push({ atMs: arrivalMs, originMs: arrivalMs - rttMs / 2 - serverFrame * FRAME_MS });
