     3	interface OriginSample {
     4	  readonly atMs: number;
     5	  readonly originMs: number;
     6	}
     7	
     8	/**
     9	 * The client's estimate of the server's duel frame, from the frames the server stamps on its messages and the
    10	 * measured round trip. Each message that left the server right after frame F and arrived at local time T suggests
    11	 * that the server's frame 0 was at `T - rtt / 2 - F * FRAME_MS` on the local clock. Delays only ever add, so the
    12	 * earliest suggestion within the last `windowMs` is the estimate: jitter and stalls behind a lost packet are ignored,
    13	 * and a server that drifts is followed within the window.
    14	 *
    15	 * Pure: the caller passes every time in milliseconds on one monotonic local clock (for example `performance.now()`).
    16	 */
    17	export class DuelClock {
    18	  private readonly samples: OriginSample[] = [];
    19	  private origin: number | undefined;
    20	
    21	  constructor(private readonly windowMs = 2000) {}
    22	
    23	  /** A message stamped with server frame `serverFrame` arrived at `arrivalMs`, with the round trip currently `rttMs`. */
    24	  observe(serverFrame: number, arrivalMs: number, rttMs: number): void {
    25	    this.samples.push({ atMs: arrivalMs, originMs: arrivalMs - rttMs / 2 - serverFrame * FRAME_MS });
    26	    while (this.samples.length > 1 && this.samples[0]!.atMs < arrivalMs - this.windowMs) this.samples.shift();
    27	    this.origin = Math.min(...this.samples.map((sample) => sample.originMs));
    28	  }
    29	
    30	  get synced(): boolean {
    31	    return this.origin !== undefined;
    32	  }
    33	
    34	  /** The server's current frame (fractional) at local time `nowMs`, or undefined before the first observation. */
    35	  serverFrameAt(nowMs: number): number | undefined {
    36	    return this.origin === undefined ? undefined : (nowMs - this.origin) / FRAME_MS;
    37	  }
    38	
    39	  /** Forgets every observation, for example after the connection was replaced. */
    40	  reset(): void {
    41	    this.samples.length = 0;
    42	    this.origin = undefined;
    43	  }
    44	}
