    31	  private readonly fresh: DuelFeedEvent[] = [];
    32	
    33	  /** Records the events of a state just simulated (predicted, replayed or confirmed). */
    34	  observe(state: DuelState): void {
    35	    for (const event of state.events) this.add({ id: duelEventId(state.frame, event), frame: state.frame, event, result: null });
