     1	/** One duel frame in milliseconds (60 Hz, §8). */
     2	export const FRAME_MS = 1000 / 60;
     3	
     4	/** The shared input delay's bounds, in frames (§15). */
     5	export const MIN_INPUT_DELAY = 3;
     6	export const MAX_INPUT_DELAY = 8;
     7	
     8	/**
     9	 * Frames of margin the input delay adds on top of the one-way latency: one for the client's send cadence (a message
    10	 * every second frame) and one for the error of the client's estimate of the server's frame.
    11	 */
    12	export const INPUT_DELAY_MARGIN_FRAMES = 2;
    13	
    14	/** A connection as the server measured it from its round-trip probes. */
    15	export interface LinkStats {
    16	  /** Median round-trip time, in milliseconds. */
    17	  readonly rttMs: number;
    18	  /** Interquartile range of the round-trip samples: their spread without the rare stall behind a lost packet. */
    19	  readonly jitterMs: number;
    20	  readonly samples: number;
    21	}
    22	
    23	function quantile(sorted: readonly number[], q: number): number {
    24	  const position = (sorted.length - 1) * q;
    25	  const low = Math.floor(position);
    26	  const high = Math.ceil(position);
    27	  return sorted[low]! + (sorted[high]! - sorted[low]!) * (position - low);
    28	}
    29	
    30	/** Round-trip samples summarised as median and interquartile range; undefined without samples. */
    31	export function linkStats(rttSamplesMs: readonly number[]): LinkStats | undefined {
    32	  if (rttSamplesMs.length === 0) return undefined;
    33	  const sorted = [...rttSamplesMs].sort((a, b) => a - b);
    34	  return { rttMs: quantile(sorted, 0.5), jitterMs: quantile(sorted, 0.75) - quantile(sorted, 0.25), samples: sorted.length };
    35	}
    36	
    37	/**
    38	 * The shared input delay for a duel (§15), chosen once from both players' links: enough frames for the slower
    39	 * player's input to cross one way (half the round trip, plus twice the jitter) before the server steps the frame it is
    40	 * tagged for, plus INPUT_DELAY_MARGIN_FRAMES, kept within [MIN_INPUT_DELAY, MAX_INPUT_DELAY]. A player with no
    41	 * measurement gets the maximum. Inputs that still arrive late (a loss stall) are substituted and corrected by rollback.
    42	 */
    43	export function chooseInputDelay(links: readonly (LinkStats | undefined)[]): number {
    44	  if (links.length === 0 || links.some((link) => link === undefined)) return MAX_INPUT_DELAY;
    45	  const oneWayMs = Math.max(...links.map((link) => link!.rttMs / 2 + 2 * link!.jitterMs));
    46	  const frames = Math.ceil(oneWayMs / FRAME_MS) + INPUT_DELAY_MARGIN_FRAMES;
    47	  return Math.min(MAX_INPUT_DELAY, Math.max(MIN_INPUT_DELAY, frames));
    48	}

