286	    if (check.snapshot === undefined) return;
287	    // The server's state is the authority: restart from it and predict forward again.
288	    this.states.set(frame, restoreDuel(this.config, check.snapshot));
289	    this.stats.snapshotRestores++;
290	    this.replayFrom(frame);
291	  }
292	
293	  /** Discards the timeline and restarts from a server snapshot at `frame`, keeping the local inputs. */
294	  private restartFrom(frame: number, snapshot: unknown, lastPair: readonly [number, number] | undefined): void {
295	    const restored = restoreDuel(this.config, snapshot);
296	    const previousHead = this.head;
297	    this.states.clear();
298	    this.used.clear();
299	    // Confirmed inputs after the snapshot stay only while they follow it without a hole.
300	    let next = frame + 1;
301	    while (this.confirmed.has(next)) next++;
302	    for (const key of [...this.confirmed.keys()]) if (key <= frame || key >= next) this.confirmed.delete(key);
303	    for (const key of [...this.checks.keys()]) if (key <= frame) this.checks.delete(key);
304	    this.states.set(frame, restored);
305	    this.head = frame;
306	    this.confirmedThrough = frame;
307	    this.receivedThrough = next - 1;
308	    if (lastPair !== undefined) this.lastConfirmed = [sanitizeDuelInput(lastPair[0]), sanitizeDuelInput(lastPair[1])];
309	    this.awaitingSnapshot = false;
310	    this.stats.snapshotRestores++;
311	    const target = Math.min(previousHead, frame + this.historyFrames);
312	    const stepped = this.stepTo(target);
313	    this.stats.replayedFrames += stepped;
314	    this.stats.deepestReplay = Math.max(this.stats.deepestReplay, stepped);
315	  }
316	
317	  private prune(): void {
318	    const keepFrom = Math.min(this.confirmedThrough, this.head - this.historyFrames);
319	    for (const map of [this.states, this.used] as const) for (const key of map.keys()) if (key < keepFrom) map.delete(key);
320	    const inputsFrom = this.confirmedThrough - this.historyFrames;
321	    for (const map of [this.confirmed, this.local] as const) for (const key of map.keys()) if (key < inputsFrom) map.delete(key);
322	    for (const key of this.checks.keys()) if (key < inputsFrom) this.checks.delete(key);
323	    this.feed.prune(inputsFrom);
324	  }
