  1	import { matchMaker } from "colyseus";
  2	import { afterAll, beforeAll, describe, expect, it } from "vitest";
  3	import { DuelRoom, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
  4	import { duelInput as I } from "@pirate-sea-race/simulation/duel";
  5	import { HeadlessDuelClient, ImpairmentProxy, logFromBundles, replayRecordedDuel, type DuelScript, type Impairment } from "@pirate-sea-race/test-tools";
  6	
  7	/**
  8	 * The impairment harness (§19 "Network and performance targets"): two headless duel clients, running the same
  9	 * rollback core as the browser, fight a scripted duel through a proxy that delays, jitters and loses messages the
 10	 * way a WebSocket over TCP suffers them. Each scenario must show:
 11	 *
 12	 * - zero desyncs: at every bundle's frame (a snapshot or a hash every 50 ms) each client hashes its own simulated
 13	 *   state, before restoring anything, and compares it with the server's;
 14	 * - zero input messages dropped by the server's rate cap;
 15	 * - corrections within the threshold: at most one per change of the opponent's input the server applied, plus one
 16	 *   per own input the server had to substitute, and never more than CORRECTIONS_PER_SECOND on average.
 17	 *
 18	 * The counts are printed and attached to the test as annotations.
 19	 */
 20	const CORRECTIONS_PER_SECOND = 8;
 21	/** Frames of scripted play (eight seconds); both clients must then confirm SETTLE_FRAMES more. */
 22	const PLAY_FRAMES = 480;
 23	const SETTLE_FRAMES = 60;
 24	
 25	const R = I("right");
 26	const L = I("left");
 27	const D = I("down");
 28	const U = I("up");
 29	const J = I("light");
 30	const K = I("heavy");
 31	
 32	/**
 33	 * Player one walks in, then cycles through a tapped jab, a held heavy, a throw pressed with rollover (K a frame after
 34	 * J), backing off, a low sweep, and a jab timed to trade with player two's.
 35	 */
 36	const attacker: DuelScript = (frame) => {
 37	  if (frame < 40) return R;
 38	  const beat = (frame - 40) % 180;
 39	  if (beat === 10) return J;
 40	  if (beat >= 30 && beat < 34) return K;
 41	  if (beat === 60) return J;
 42	  if (beat > 60 && beat < 65) return J | K;
 43	  if (beat >= 100 && beat < 120) return L;
 44	  if (beat >= 120 && beat < 126) return R;
 45	  if (beat >= 126 && beat < 128) return D | K;
 46	  if (beat >= 150 && beat < 153) return J;
 47	  if (beat >= 153) return R;
 48	  return 0;
 49	};
 50	
 51	/** Player two guards standing and crouching, punishes with a jab, throws, jumps, and jabs into player one's jab. */
 52	const defender: DuelScript = (frame) => {
 53	  if (frame < 40) return 0;
 54	  const beat = (frame - 40) % 180;
 55	  if (beat < 30) return R;
 56	  if (beat === 41) return J;
 57	  if (beat >= 60 && beat < 63) return R;
 58	  if (beat === 80) return J;
 59	  if (beat > 80 && beat < 85) return J | K;
 60	  if (beat === 90) return U;
 61	  if (beat >= 100 && beat < 130) return D | R;
 62	  if (beat === 130 || beat === 150) return J;
 63	  return 0;
 64	};
 65	
 66	interface ScenarioReport {
 67	  readonly scenario: string;
 68	  readonly inputDelay: number;
 69	  readonly corrections: [number, number];
 70	  readonly correctionBound: [number, number];
 71	  readonly substituted: [number, number];
 72	  readonly hashChecks: [number, number];
 73	  readonly desyncs: [number, number];
 74	  readonly deepestReplay: [number, number];
 75	  readonly rateLimited: [number, number];
 76	  readonly lostMessages: number;
 77	}
 78	
 79	let server: RunningGameServer;
 80	
 81	beforeAll(async () => {
 82	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false });
 83	});
 84	
 85	afterAll(async () => {
 86	  await server.close();
 87	});
 88	
 89	/** How often the input a player's opponent actually had applied changed, from the frames the server confirmed. */
 90	function opponentChanges(client: HeadlessDuelClient, through: number): number {
 91	  const log = logFromBundles(client.bundles).inputs.slice(0, through);
 92	  const opponent = client.slot === 0 ? 1 : 0;
 93	  return log.filter((pair, index) => index > 0 && pair[opponent] !== log[index - 1]![opponent]).length;
 94	}
 95	
 96	async function runScenario(scenario: string, impairment: Impairment, seed: number): Promise<ScenarioReport> {
 97	  const proxies = await Promise.all([ImpairmentProxy.start(server.port, impairment, seed), ImpairmentProxy.start(server.port, impairment, seed + 1)]);
 98	  const host = await HeadlessDuelClient.create(proxies[0].endpoint);
 99	  const guest = await HeadlessDuelClient.join(proxies[1].endpoint, host.code);
100	  const players = [host, guest] as const;
101	  try {
102	    host.play((frame) => (frame <= PLAY_FRAMES ? attacker(frame, host.duel!) : 0));
103	    guest.play((frame) => (frame <= PLAY_FRAMES ? defender(frame, guest.duel!) : 0));
104	    await host.waitFor(() => host.phase === "fighting", 8000);
105	    for (const player of players) await player.waitForConfirmed(PLAY_FRAMES + SETTLE_FRAMES, 30_000);
106	    const room = matchMaker.getLocalRoomById(host.room.roomId) as unknown as DuelRoom;
107	    const diagnostics = room.diagnostics();
108	
109	    // Determinism on top of the live hash checks: the pairs each client received replay to the server's state.
110	    for (const player of players) {
111	      const log = logFromBundles(player.bundles);
112	      const serverLog = room.inputLog();
113	      const replayed = await replayRecordedDuel(log, { seed: room.state.seed });
114	      const fromServer = await replayRecordedDuel({ ...serverLog, inputs: serverLog.inputs.slice(0, log.inputs.length) }, { seed: room.state.seed });
115	      expect(log.inputs.length).toBeGreaterThanOrEqual(PLAY_FRAMES + SETTLE_FRAMES);
116	      expect(replayed.hash).toBe(fromServer.hash);
117	    }
118	    const through = PLAY_FRAMES + SETTLE_FRAMES;
119	    const pair = <T>(pick: (player: HeadlessDuelClient, index: 0 | 1) => T): [T, T] => [pick(host, 0), pick(guest, 1)];
120	    return {
121	      scenario,
122	      inputDelay: diagnostics.inputDelay,
123	      corrections: pair((player) => player.stats!.corrections),
124	      correctionBound: pair((player, index) => opponentChanges(player, through) + player.stats!.substitutedFrames[index]),
125	      substituted: [diagnostics.authority.repeated[0] + diagnostics.authority.neutral[0], diagnostics.authority.repeated[1] + diagnostics.authority.neutral[1]],
126	      hashChecks: pair((player) => player.stats!.hashChecks),
127	      desyncs: pair((player) => player.stats!.desyncs),
128	      deepestReplay: pair((player) => player.stats!.deepestReplay),
129	      rateLimited: [diagnostics.dropped["0"]!["rate-limited"], diagnostics.dropped["1"]!["rate-limited"]],
130	      lostMessages: proxies[0].stats.lost[0] + proxies[0].stats.lost[1] + proxies[1].stats.lost[0] + proxies[1].stats.lost[1],
131	    };
132	  } finally {
133	    await Promise.all(players.map((player) => player.leave()));
134	    await Promise.all(proxies.map((proxy) => proxy.close()));
135	  }
136	}
137	
138	function expectWithinBudget(report: ScenarioReport): void {
139	  expect(report.desyncs).toEqual([0, 0]);
140	  expect(report.rateLimited).toEqual([0, 0]);
141	  const settled = PLAY_FRAMES + SETTLE_FRAMES;
142	  for (const index of [0, 1] as const) {
143	    // A bundle every 3 frames, each checked once its frame is confirmed.
144	    expect(report.hashChecks[index]).toBeGreaterThanOrEqual(Math.floor(settled / 3) - 5);
145	    expect(report.corrections[index]).toBeLessThanOrEqual(report.correctionBound[index]);
146	    expect(report.corrections[index]).toBeLessThanOrEqual((CORRECTIONS_PER_SECOND * settled) / 60);
147	  }
148	}
149	
150	describe("duel netcode through the impairment harness", () => {
151	  const scenarios: readonly [string, Impairment, number][] = [
152	    ["no impairment", { rttMs: 0, jitterMs: 0, loss: 0 }, 11],
153	    ["80 ms round trip, 20 ms jitter, 1% loss", { rttMs: 80, jitterMs: 20, loss: 0.01 }, 21],
154	  ];
155	  for (const [scenario, impairment, seed] of scenarios) it(`keeps both clients on the server's state with ${scenario}`, async ({ annotate }) => {
156	    const report = await runScenario(scenario, impairment, seed);
157	    console.log(`duel harness: ${JSON.stringify(report)}`);
158	    await annotate(
159	      `${scenario}: input delay ${report.inputDelay}; corrections ${report.corrections.join("/")} (bound ${report.correctionBound.join("/")}); ` +
160	        `server substitutions ${report.substituted.join("/")}; hash checks ${report.hashChecks.join("/")}, desyncs ${report.desyncs.join("/")}; ` +
161	        `deepest replay ${report.deepestReplay.join("/")} frames; rate-limited drops ${report.rateLimited.join("/")}; lost messages ${report.lostMessages}`,
162	    );
163	    expectWithinBudget(report);
164	    if (impairment.loss > 0) expect(report.lostMessages).toBeGreaterThan(0);
165	  }, 60_000);
166	});

