  2	import { nextRandom } from "@pirate-sea-race/simulation";
  3	
  4	/**
  5	 * How the proxy impairs a connection, per §19's scenarios. Each direction delays every message by half the round
  6	 * trip plus a uniform offset within ±jitter/2, so round trips spread over `rttMs ± jitterMs`; a message is lost with
  7	 * probability `loss`, and like TCP it is then retransmitted after `rtoMs`.
  8	 */
  9	export interface Impairment {
 10	  readonly rttMs: number;
 11	  readonly jitterMs: number;
 12	  /** From 0 to 1. */
 13	  readonly loss: number;
 14	  /** The retransmission timeout a lost message waits (default 200 ms, TCP's minimum RTO on Linux). */
 15	  readonly rtoMs?: number;
 16	}
 17	
 18	export const NO_IMPAIRMENT: Impairment = { rttMs: 0, jitterMs: 0, loss: 0 };
 19	
 20	export interface ImpairmentStats {
 21	  /** Messages (WebSocket frames, or raw chunks before the upgrade) forwarded, client→server and server→client. */
 22	  readonly messages: [number, number];
 23	  /** Of those, the ones "lost" and held for a retransmission timeout. */
 24	  readonly lost: [number, number];
 25	  /** The longest time a message spent in the proxy, in milliseconds. */
 26	  readonly longestHoldMs: number;
 27	}
 28	
 29	const HEADER_END = Buffer.from("\r\n\r\n");
 30	
 31	/** Splits a byte stream into whole WebSocket frames (RFC 6455 §5.2) without decoding them. */
 32	class FrameSplitter {
 33	  private pending: Buffer = Buffer.alloc(0);
 34	
 35	  push(chunk: Buffer): Buffer[] {
 36	    this.pending = this.pending.length === 0 ? chunk : Buffer.concat([this.pending, chunk]);
 37	    const frames: Buffer[] = [];
 38	    for (;;) {
 39	      const length = frameLength(this.pending);
 40	      if (length === undefined || this.pending.length < length) return frames;
 41	      frames.push(this.pending.subarray(0, length));
 42	      this.pending = this.pending.subarray(length);
 43	    }
 44	  }
 45	}
 46	
 47	/** The total length of the frame at the start of `bytes`, or undefined until its header is complete. */
 48	function frameLength(bytes: Buffer): number | undefined {
 49	  if (bytes.length < 2) return undefined;
 50	  const masked = (bytes[1]! & 0x80) !== 0;
 51	  const short = bytes[1]! & 0x7f;
 52	  let header = 2;
 53	  let payload = short;
 54	  if (short === 126) {
 55	    if (bytes.length < 4) return undefined;
 56	    payload = bytes.readUInt16BE(2);
 57	    header = 4;
 58	  } else if (short === 127) {
 59	    if (bytes.length < 10) return undefined;
 60	    payload = Number(bytes.readBigUInt64BE(2));
 61	    header = 10;
 62	  }
 63	  return header + (masked ? 4 : 0) + payload;
 64	}
 65	
 66	type Direction = 0 | 1;
 67	
 68	/**
 69	 * One direction of one connection. Until the HTTP upgrade completes, raw chunks travel as they arrive; after it, whole
 70	 * WebSocket frames, each one a message. Messages keep their order: each leaves at the later of its own delivery time
 71	 * and the previous message's, so jitter only delays, and a lost message holds up everything queued behind it (the
 72	 * head-of-line stall of a reliable ordered stream).
 73	 */
 74	class Pipe {
 75	  /** Reading the first HTTP head; then raw bytes (plain HTTP), or WebSocket frames after an upgrade. */
 76	  private mode: "head" | "raw" | "frames" = "head";
 77	  private header: Buffer = Buffer.alloc(0);
 78	  private readonly splitter = new FrameSplitter();
 79	  private readonly queue: { at: number; data: Buffer | "end"; queuedAt: number }[] = [];
 80	  private lastAt = 0;
 81	  private timer: NodeJS.Timeout | undefined;
 82	
 83	  constructor(
 84	    private readonly proxy: ImpairmentProxy,
 85	    private readonly direction: Direction,
 86	    private readonly to: Socket,
 87	  ) {}
 88	
 89	  /** Bytes arriving from the source socket. */
 90	  push(chunk: Buffer): void {
 91	    if (this.mode === "frames") {
 92	      for (const frame of this.splitter.push(chunk)) this.enqueue(frame);
 93	      return;
 94	    }
 95	    if (this.mode === "raw") {
 96	      this.enqueue(chunk);
 97	      return;
 98	    }
 99	    this.header = Buffer.concat([this.header, chunk]);
100	    const end = this.header.indexOf(HEADER_END);
101	    if (end < 0) return;
102	    const head = this.header.subarray(0, end + HEADER_END.length);
103	    const rest = this.header.subarray(end + HEADER_END.length);
104	    this.header = Buffer.alloc(0);
105	    this.enqueue(head);
106	    const text = head.toString("latin1");
107	    const upgrade = this.direction === 0 ? /^upgrade:\s*websocket/im.test(text) : /^HTTP\/1\.1 101/.test(text);
108	    this.mode = upgrade ? "frames" : "raw";
109	    if (rest.length > 0) this.push(rest);
110	  }
111	
112	  /** The source ended: the end follows the data still queued. */
113	  end(): void {
114	    this.enqueue("end");
115	  }
116	
117	  stop(): void {
118	    clearTimeout(this.timer);
119	    this.queue.length = 0;
120	  }
121	
122	  private enqueue(data: Buffer | "end"): void {
123	    const now = performance.now();
124	    const at = Math.max(this.lastAt, now + this.proxy.delayFor(this.direction, data !== "end"));
125	    this.lastAt = at;
126	    this.queue.push({ at, data, queuedAt: now });
127	    if (this.queue.length === 1) this.schedule();
128	  }
129	
130	  private schedule(): void {
131	    const head = this.queue[0];
132	    if (head === undefined) return;
133	    this.timer = setTimeout(() => this.flush(), Math.max(0, head.at - performance.now()));
134	  }
135	
136	  private flush(): void {
137	    const now = performance.now();
138	    while (this.queue.length > 0 && this.queue[0]!.at <= now + 0.5) {
139	      const { data, queuedAt } = this.queue.shift()!;
140	      this.proxy.held(now - queuedAt);
141	      if (!this.to.writable) continue;
142	      if (data === "end") this.to.end();
143	      else this.to.write(data);
144	    }
145	    this.schedule();
146	  }
147	}
148	
149	/**
150	 * A TCP proxy in front of the game server that impairs traffic the way a real network impairs a WebSocket (§15,
151	 * §19): latency and jitter delay messages without ever reordering them, and loss becomes a stall of about one
152	 * retransmission timeout for the lost message and everything behind it. HTTP (matchmaking) passes through the same
153	 * delays. The random source is seeded, so a run's losses and delays repeat.
154	 */
155	export class ImpairmentProxy {
156	  private readonly sockets = new Set<Socket>();
157	  private readonly pipes = new Set<Pipe>();
158	  private random: number;
159	  private refusing = false;
160	  private readonly counters = { messages: [0, 0] as [number, number], lost: [0, 0] as [number, number], longestHoldMs: 0 };
161	
162	  private constructor(
163	    private readonly server: Server,
164	    private impairment: Impairment,
165	    seed: number,
166	  ) {
167	    this.random = seed >>> 0;
168	  }
169	
170	  /** Starts a proxy on a free local port that forwards to `target` (the game server's port on 127.0.0.1). */
171	  static async start(targetPort: number, impairment: Impairment = NO_IMPAIRMENT, seed = 1): Promise<ImpairmentProxy> {
172	    let proxy: ImpairmentProxy | undefined;
173	    // Half-open sockets let each direction finish on its own: an end is forwarded after the data queued before it.
174	    const server = createServer({ allowHalfOpen: true }, (client) => proxy!.accept(client, targetPort));
175	    proxy = new ImpairmentProxy(server, impairment, seed);
176	    await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
177	    return proxy;
178	  }
179	
180	  /** The address clients use instead of the server's, for example `http://127.0.0.1:41234`. */
181	  get endpoint(): string {
182	    return `http://127.0.0.1:${(this.server.address() as AddressInfo).port}`;
183	  }
184	
185	  get stats(): ImpairmentStats {
186	    return { messages: [...this.counters.messages], lost: [...this.counters.lost], longestHoldMs: this.counters.longestHoldMs };
187	  }
188	
189	  setImpairment(impairment: Impairment): void {
190	    this.impairment = impairment;
191	  }
192	
193	  /**
194	   * Cuts every open connection at once, as a dropped network would (no WebSocket close frame). With `refuse`, new
195	   * connections are refused too until `restore()`, so a client cannot come back.
196	   */
197	  sever(options: { refuse?: boolean } = {}): void {
198	    this.refusing = options.refuse ?? false;
199	    for (const pipe of this.pipes) pipe.stop();
200	    for (const socket of this.sockets) socket.destroy();
201	  }
202	
203	  restore(): void {
204	    this.refusing = false;
205	  }
206	
207	  async close(): Promise<void> {
208	    this.sever();
209	    await new Promise<void>((resolve) => this.server.close(() => resolve()));
210	  }
211	
212	  /** The delay for the next message in one direction; counts it, and decides whether it is lost. */
213	  delayFor(direction: Direction, message: boolean): number {
214	    const { rttMs, jitterMs, loss, rtoMs = 200 } = this.impairment;
215	    const delay = Math.max(0, rttMs / 2 + (this.draw() - 0.5) * jitterMs);
216	    if (!message) return delay;
217	    this.counters.messages[direction]++;
218	    if (loss > 0 && this.draw() < loss) {
219	      this.counters.lost[direction]++;
220	      return delay + rtoMs;
221	    }
222	    return delay;
223	  }
224	
225	  held(ms: number): void {
226	    this.counters.longestHoldMs = Math.max(this.counters.longestHoldMs, ms);
227	  }
228	
229	  /** A uniform draw in [0, 1) from the seeded generator. */
230	  private draw(): number {
231	    const next = nextRandom(this.random);
232	    this.random = next.state;
233	    return next.value / 2 ** 32;
234	  }
235	
236	  private accept(client: Socket, targetPort: number): void {
237	    if (this.refusing) {
238	      client.destroy();
239	      return;
240	    }
241	    const upstream = connect({ port: targetPort, host: "127.0.0.1", allowHalfOpen: true });
242	    for (const socket of [client, upstream]) {
243	      socket.setNoDelay(true);
244	      this.sockets.add(socket);
245	      socket.once("close", () => this.sockets.delete(socket));
246	    }
247	    const up = new Pipe(this, 0, upstream);
248	    const down = new Pipe(this, 1, client);
249	    this.pipes.add(up);
250	    this.pipes.add(down);
251	    const teardown = () => {
252	      this.pipes.delete(up);
253	      this.pipes.delete(down);
254	    };
255	    client.on("data", (chunk: Buffer) => up.push(chunk));
256	    upstream.on("data", (chunk: Buffer) => down.push(chunk));
257	    client.on("end", () => up.end());
258	    upstream.on("end", () => down.end());
259	    // A reset on either side resets the other, like a broken path.
260	    client.on("error", () => upstream.destroy());
261	    upstream.on("error", () => client.destroy());
262	    client.on("close", (hadError) => {
263	      teardown();
264	      if (hadError) upstream.destroy();
265	    });
266	    upstream.on("close", (hadError) => {
267	      teardown();
268	      if (hadError) client.destroy();
269	    });
270	  }
271	}
  1	import { readFile } from "node:fs/promises";
  2	import {
  3	  createDuelInputLog,
  4	  createDuelState,
  5	  defaultDuelConfig,
  6	  replayDuel,
  7	  type DuelConfig,
  8	  type DuelInputLog,
  9	  type DuelInputs,
 10	  type DuelReplay,
 11	} from "@pirate-sea-race/simulation/duel";
 12	
 13	/**
 14	 * Replays a recorded duel input log (§19 "Combat determinism") from the frame-0 state of the duel's seed, and returns
 15	 * its final state and hash. `log` is the parsed JSON (or a path to it); `replayDuel` validates it and refuses a log
 16	 * recorded on other move data.
 17	 */
 18	export async function replayRecordedDuel(log: unknown, options: { readonly seed: number; readonly config?: DuelConfig }): Promise<DuelReplay> {
 19	  const parsed: unknown = typeof log === "string" ? JSON.parse(await readFile(log, "utf8")) : log;
 20	  const config = options.config ?? defaultDuelConfig;
 21	  return replayDuel(config, createDuelState(config, { seed: options.seed }), parsed);
 22	}
 23	
 24	/**
 25	 * The input log a client can rebuild from the frame bundles it received: the pairs the server applied, from frame 1
 26	 * up to the last frame received without a gap. Replaying it must reproduce the server's state.
 27	 */
 28	export function logFromBundles(bundles: readonly { readonly frame: number; readonly inputs: readonly (readonly [number, number])[] }[], config: DuelConfig = defaultDuelConfig): DuelInputLog {
 29	  const pairs: DuelInputs[] = [];
 30	  for (const bundle of bundles) {
 31	    const first = bundle.frame - bundle.inputs.length + 1;
 32	    bundle.inputs.forEach((pair, index) => {
 33	      const frame = first + index;
 34	      if (frame === pairs.length + 1) pairs.push([pair[0], pair[1]]);
 35	    });
 36	  }
 37	  return createDuelInputLog(config, 0, pairs);
 38	}

