 13	/**
 14	 * Replays a recorded duel input log (§19 "Combat determinism") from the frame-0 state of the duel's seed, and returns
 15	 * its final state and hash. `log` is the parsed JSON (or a path to it); `replayDuel` validates it and refuses a log
 16	 * recorded on other move data.
 17	 */
 18	export async function replayRecordedDuel(log: unknown, options: { readonly seed: number; readonly config?: DuelConfig }): Promise<DuelReplay> {
 19	  const parsed: unknown = typeof log === "string" ? JSON.parse(await readFile(log, "utf8")) : log;
 20	  const config = options.config ?? defaultDuelConfig;
 21	  return replayDuel(config, createDuelState(config, { seed: options.seed }), parsed);
 22	}
 23	
 24	/**
 25	 * The input log a client can rebuild from the frame bundles it received: the pairs the server applied, from frame 1
 26	 * up to the last frame received without a gap. Replaying it must reproduce the server's state.
 27	 */
 28	export function logFromBundles(bundles: readonly { readonly frame: number; readonly inputs: readonly (readonly [number, number])[] }[], config: DuelConfig = defaultDuelConfig): DuelInputLog {
 29	  const pairs: DuelInputs[] = [];
 30	  for (const bundle of bundles) {
 31	    const first = bundle.frame - bundle.inputs.length + 1;
 32	    bundle.inputs.forEach((pair, index) => {
 33	      const frame = first + index;
 34	      if (frame === pairs.length + 1) pairs.push([pair[0], pair[1]]);
 35	    });
 36	  }
 37	  return createDuelInputLog(config, 0, pairs);
 38	}

