 49	/** The pairs the server applied, by frame, from the bundles a client received. */
 50	function appliedPairs(bundles: readonly DuelFrameBundle[]): Map<number, { pair: readonly [number, number]; substituted: [boolean, boolean] }> {
 51	  const pairs = new Map<number, { pair: readonly [number, number]; substituted: [boolean, boolean] }>();
 52	  for (const bundle of bundles) {
 53	    const first = bundle.frame - bundle.inputs.length + 1;
 54	    bundle.inputs.forEach((pair, index) => {
 55	      pairs.set(first + index, { pair, substituted: [((bundle.substituted >> (2 * index)) & 1) === 1, ((bundle.substituted >> (2 * index + 1)) & 1) === 1] });
 56	    });
 57	  }
 58	  return pairs;
 59	}
