211	describe("duel reconnection (§12)", () => {
212	  async function startDuel(dropperThroughProxy: boolean): Promise<{ host: HeadlessDuelClient; guest: HeadlessDuelClient; proxy: ImpairmentProxy }> {
213	    const proxy = await ImpairmentProxy.start(server.port);
214	    proxies.push(proxy);
