216	    const guest = await track(HeadlessDuelClient.join(dropperThroughProxy ? proxy.endpoint : endpoint, host.code));
217	    // The guest walks towards the host all the time, so its held input is left.
218	    guest.play(() => duelInput("left"));
219	    await host.waitFor(() => host.phase === "fighting", 5000);
220	    // The SDK reconnects only a room joined at least five seconds ago.
221	    await host.waitForConfirmed(180);
