229	    // The network drops and stays down for about a second.
230	    proxy.sever({ refuse: true });
231	    await host.waitFor(() => !room.state.seats.find((seat) => seat.slot === 1)!.connected, 5000);
232	    // While the guest is away the server substitutes: its held input (left) for 15 frames, then neutral.
233	    await host.waitFor(() => latestFrame(host) >= dropFrame + 50);
234	    const during = [...appliedPairs(host.bundles).entries()].filter(([frame]) => frame > dropFrame && frame <= dropFrame + 50);
235	    const substituted = during.filter(([, entry]) => entry.substituted[1]).map(([, entry]) => entry.pair[1]);
236	    expect(substituted.slice(0, INPUT_HOLD_FRAMES)).toEqual(hold(INPUT_HOLD_FRAMES, duelInput("left")));
237	    expect(substituted.slice(INPUT_HOLD_FRAMES).length).toBeGreaterThan(0);
238	    expect(substituted.slice(INPUT_HOLD_FRAMES).every((bits) => bits === 0)).toBe(true);
239	    await sleep(500);
240	    proxy.restore();
241	    // The SDK reconnects on its own through the same address, within the ten seconds.
242	    await guest.waitFor(() => guest.connected && room.state.seats.find((seat) => seat.slot === 1)!.connected, 9000);
243	    const back = room.duelState.frame;
244	    await guest.waitForConfirmed(back + 60);
245	    expect(room.state.phase).toBe("fighting");
246	    // The rejoined client restarted from the server's snapshot and follows the server again, without a desync.
247	    expect(guest.stats!.snapshotRestores).toBeGreaterThanOrEqual(1);
248	    expect(guest.stats!.desyncs).toBe(0);
249	    const frame = guest.duel!.rollback.confirmedFrame;
250	    const replayed = await replayRecordedDuel({ ...room.inputLog(), inputs: room.inputLog().inputs.slice(0, frame) }, { seed: room.state.seed });
251	    expect(hashState(guest.duel!.confirmedState)).toBe(replayed.hash);
252	    const guestPairs = appliedPairs(host.bundles);
253	    expect([...guestPairs.entries()].some(([f, entry]) => f > back + 10 && !entry.substituted[1] && entry.pair[1] === duelInput("left"))).toBe(true);
