     1	import type { Room } from "@colyseus/sdk";
     2	
     3	/**
     4	 * Development only (`npm run dev`; main.ts imports this module only when `import.meta.env.DEV`, so the production
     5	 * build does not contain it): delays everything a room's socket sends and receives, the server's round-trip probes
     6	 * and Colyseus's own pings included, by half of `rttMs` each way plus a uniform ±jitter/2, never reordering. It lets
     7	 * the operator playtest §19's latencies on one machine: `?rtt=80&jitter=20`.
     8	 */
     9	export const DEV_LATENCY_MARKER = "pirate-sea-race dev latency";
    10	
    11	export interface DevLatency {
    12	  readonly rttMs: number;
    13	  readonly jitterMs: number;
    14	}
    15	
    16	/** The setting from the page's query string, or undefined when it asks for none. */
    17	export function devLatencyFromQuery(search: string): DevLatency | undefined {
    18	  const query = new URLSearchParams(search);
    19	  const rttMs = Number(query.get("rtt") ?? 0);
    20	  const jitterMs = Number(query.get("jitter") ?? 0);
    21	  if (!(rttMs > 0 || jitterMs > 0) || !Number.isFinite(rttMs) || !Number.isFinite(jitterMs)) return undefined;
    22	  return { rttMs: Math.max(0, rttMs), jitterMs: Math.max(0, jitterMs) };
    23	}
    24	
    25	/** An ordered delay line: each item leaves at the later of its own time and the previous item's. */
    26	class DelayLine {
    27	  private last = 0;
    28	
    29	  constructor(private readonly latency: DevLatency) {}
    30	
    31	  push(deliver: () => void): void {
    32	    const delay = Math.max(0, this.latency.rttMs / 2 + (Math.random() - 0.5) * this.latency.jitterMs);
    33	    const at = Math.max(this.last, performance.now() + delay);
    34	    this.last = at;
    35	    setTimeout(deliver, at - performance.now());
    36	  }
    37	}
    38	
    39	/** Wraps a joined room's connection in both directions. It survives the SDK's reconnection, which reuses both hooks. */
    40	export function applyDevLatency(room: Room, latency: DevLatency): void {
    41	  console.info(`${DEV_LATENCY_MARKER}: ${latency.rttMs} ms round trip, ${latency.jitterMs} ms jitter`);
    42	  const connection = room.connection as unknown as {
    43	    transport: { send(data: Uint8Array): void };
    44	    events: { onmessage?: (event: unknown) => void };
    45	  };
    46	  const outgoing = new DelayLine(latency);
    47	  const send = connection.transport.send.bind(connection.transport);
    48	  connection.transport.send = (data: Uint8Array) => {
    49	    const copy = new Uint8Array(data);
    50	    outgoing.push(() => {
    51	      try {
    52	        send(copy);
    53	      } catch {
    54	        // The socket closed meanwhile; a real network would have lost it too.
    55	      }
    56	    });
    57	  };
    58	  const incoming = new DelayLine(latency);
    59	  const receive = connection.events.onmessage;
    60	  connection.events.onmessage = (event: unknown) => incoming.push(() => receive?.call(connection.events, event));
    61	}
