     3	/** The duel's keyboard defaults (§8): WASD or the arrows move, J light, K heavy, U and I the specials, Shift dash. */
     4	export const DUEL_KEYS: Readonly<Record<keyof typeof DUEL_INPUT, readonly string[]>> = {
     5	  left: ["KeyA", "ArrowLeft"],
     6	  right: ["KeyD", "ArrowRight"],
     7	  up: ["KeyW", "ArrowUp"],
     8	  down: ["KeyS", "ArrowDown"],
     9	  light: ["KeyJ"],
    10	  heavy: ["KeyK"],
    11	  special1: ["KeyU"],
    12	  special2: ["KeyI"],
    13	  dash: ["ShiftLeft", "ShiftRight"],
    14	};
    15	
    16	const BIT_OF_CODE = new Map<string, number>(
    17	  (Object.entries(DUEL_KEYS) as [keyof typeof DUEL_INPUT, readonly string[]][]).flatMap(([name, codes]) => codes.map((code) => [code, DUEL_INPUT[name]] as const)),
    18	);
    19	
    20	/** The input bits for a set of held key codes. Opposite directions both held stay in: the step makes them neutral. */
    21	export function duelBits(codes: Iterable<string>): number {
    22	  let bits = 0;
    23	  for (const code of codes) bits |= BIT_OF_CODE.get(code) ?? 0;
    24	  return bits;
    25	}
    26	
    27	/**
    28	 * The duel's keyboard adapter. `bits()` is what is held now, plus every key pressed since the last frame the client
    29	 * tagged: a tap that goes down and up between two frames still counts for one frame. The caller calls `framesTagged()`
    30	 * once the pressed keys have been tagged into a frame. Every key is released when the window loses focus.
    31	 */
    32	export class DuelKeyboard {
    33	  private readonly held = new Set<string>();
    34	  private tapped = 0;
    35	
    36	  constructor(target: Window) {
    37	    target.addEventListener("keydown", (event) => {
    38	      if (!BIT_OF_CODE.has(event.code) || isTyping(event.target)) return;
    39	      event.preventDefault();
    40	      this.press(event.code);
    41	    });
    42	    target.addEventListener("keyup", (event) => this.release(event.code));
    43	    target.addEventListener("blur", () => this.held.clear());
    44	  }
    45	
    46	  press(code: string): void {
    47	    this.held.add(code);
    48	    this.tapped |= BIT_OF_CODE.get(code) ?? 0;
    49	  }
    50	
    51	  release(code: string): void {
    52	    this.held.delete(code);
    53	  }
    54	
    55	  bits(): number {
    56	    return duelBits(this.held) | this.tapped;
    57	  }
    58	
    59	  /** The keys pressed so far have made it into a tagged frame; a tap released since then no longer counts. */
    60	  framesTagged(): void {
    61	    this.tapped = 0;
    62	  }
    63	}
    64	
    65	/** Keys typed into a text field or a menu are not moves; a checkbox or a button does not take them. */
    66	function isTyping(target: EventTarget | null): boolean {
    67	  if (target instanceof HTMLInputElement) return target.type !== "checkbox" && target.type !== "button";
    68	  return target instanceof HTMLTextAreaElement || target instanceof HTMLSelectElement;
    69	}
