     1	import type { DuelRoomPhase } from "@pirate-sea-race/protocol";
     2	import type { DuelState, PlayerIndex } from "@pirate-sea-race/simulation/duel";
     3	
     4	export type DuelConnectionStatus = "connected" | "reconnecting" | "disconnected";
     5	
     6	export interface DuelHudModel {
     7	  readonly code: string;
     8	  readonly practice: boolean;
     9	  readonly phase: DuelRoomPhase;
    10	  readonly status: DuelConnectionStatus;
    11	  /** This browser's player, 0 or 1. */
    12	  readonly self: PlayerIndex;
    13	  /** Frames left in the countdown. */
    14	  readonly countdown: number;
    15	  /** Seats connected, by player. */
    16	  readonly connected: readonly [boolean, boolean];
    17	  /** The newest state stepped from the server's confirmed inputs: the authoritative health, stamina and clock. */
    18	  readonly confirmed: DuelState;
    19	  readonly maxHealth: number;
    20	  readonly maxStamina: number;
    21	  readonly roundFrames: number;
    22	  readonly overtimeFrames: number;
    23	  readonly rttMs: number;
    24	  readonly inputDelay: number;
    25	  readonly corrections: number;
    26	  readonly result: { readonly winner: number; readonly reason: string } | undefined;
    27	}
    28	
    29	function field(root: ParentNode, id: string): HTMLElement {
    30	  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
    31	  if (element === null) throw new Error(`missing duel HUD field ${id}`);
    32	  return element;
    33	}
    34	
    35	/**
    36	 * The round clock in whole seconds (§7: 60 seconds, then 10 of overtime on equal health). It reads 0 on the round's
    37	 * last frame, where a timeout is decided; overtime starts on the frame after.
    38	 */
    39	export function roundClock(frame: number, roundFrames: number, overtimeFrames: number): { seconds: number; overtime: boolean } {
    40	  if (frame <= roundFrames) return { seconds: Math.ceil((roundFrames - frame) / 60), overtime: false };
    41	  return { seconds: Math.max(0, Math.ceil((roundFrames + overtimeFrames - frame) / 60)), overtime: true };
    42	}
    43	
    44	const REASONS: Record<string, string> = {
    45	  ko: "KO",
    46	  "double-ko": "double KO",
    47	  timeout: "time",
    48	  overtime: "overtime",
    49	  forfeit: "forfeit",
    50	};
    51	
    52	/** "Player 1 wins by KO", "Draw by double KO". */
    53	export function resultText(winner: number, reason: string): string {
    54	  const how = REASONS[reason] ?? reason;
    55	  return winner < 0 ? `Draw (${how})` : `Player ${winner + 1} wins by ${how}`;
    56	}
    57	
    58	function playerName(model: DuelHudModel, player: PlayerIndex): string {
    59	  if (player === model.self) return `Player ${player + 1} (you)`;
    60	  return model.practice ? `Player ${player + 1} (dummy)` : `Player ${player + 1}`;
    61	}
    62	
    63	/**
    64	 * The duel HUD (§13): both health bars and stamina, the round clock and the connection line, all from the confirmed
    65	 * (server-equal) state, then the result. Data attributes carry the exact numbers for the browser tests.
    66	 */
    67	export function renderDuelHud(root: ParentNode, model: DuelHudModel): void {
    68	  field(root, "duel-code").textContent = model.practice ? `${model.code} (practice)` : model.code;
    69	  field(root, "duel-status").textContent = model.status;
    70	  const phase = field(root, "duel-phase");
    71	  phase.textContent = model.phase === "countdown" ? `Fight in ${Math.ceil(model.countdown / 60)}` : model.phase;
    72	  phase.dataset["phase"] = model.phase;
    73	
    74	  for (const player of [0, 1] as const) {
    75	    const fighter = model.confirmed.fighters[player];
    76	    field(root, `duel-name-${player}`).textContent = `${playerName(model, player)}${model.practice && player === 1 ? "" : model.connected[player] ? "" : " (away)"}`;
    77	    const health = field(root, `duel-health-${player}`);
    78	    health.dataset["value"] = String(fighter.health);
    79	    health.style.setProperty("--fill", `${(100 * fighter.health) / model.maxHealth}%`);
    80	    field(root, `duel-health-text-${player}`).textContent = `${fighter.health} / ${model.maxHealth}`;
    81	    const stamina = field(root, `duel-stamina-${player}`);
    82	    stamina.dataset["value"] = String(fighter.stamina);
    83	    stamina.style.setProperty("--fill", `${(100 * fighter.stamina) / model.maxStamina}%`);
    84	  }
    85	
    86	  const clock = roundClock(model.confirmed.frame, model.roundFrames, model.overtimeFrames);
    87	  const clockField = field(root, "duel-clock");
    88	  clockField.textContent = clock.overtime ? `OT ${clock.seconds}` : String(clock.seconds);
    89	  clockField.dataset["frame"] = String(model.confirmed.frame);
    90	  clockField.dataset["seconds"] = String(clock.seconds);
    91	
    92	  field(root, "duel-rtt").textContent = `${Math.round(model.rttMs)} ms`;
    93	  field(root, "duel-delay").textContent = model.inputDelay > 0 ? `${model.inputDelay} frames` : "measuring";
    94	  field(root, "duel-delay").dataset["frames"] = String(model.inputDelay);
    95	  field(root, "duel-corrections").textContent = String(model.corrections);
    96	  field(root, "duel-corrections").dataset["count"] = String(model.corrections);
    97	
    98	  const result = field(root, "duel-result");
    99	  result.hidden = model.result === undefined;
   100	  if (model.result !== undefined) {
   101	    field(root, "duel-result-text").textContent = resultText(model.result.winner, model.result.reason);
   102	    result.dataset["winner"] = String(model.result.winner);
   103	    result.dataset["reason"] = model.result.reason;
   104	    result.dataset["frame"] = String(model.confirmed.frame);
   105	    result.dataset["health"] = model.confirmed.fighters.map((fighter) => fighter.health).join(",");
   106	  }
   107	}
